33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
45	
46	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	};
53	
54	/** Percentages are applied as integer arithmetic so that the final
55	 *  rounding is not corrupted by float artifacts (100 * 1.1 === 110.000…1). */
56	const addPercent = (amount: number, percent: number): number =>
57	  amount + (amount * percent) / 100;
58	
59	/** Rounds up — premiums round in the MHPCO's favour. */
60	const roundPremium = (amount: number): number => Math.ceil(amount);
61	
62	const itemBasePremium = (item: Item): number =>
63	  BASE_PREMIUM_BY_TYPE[item.type];
64	
65	const policyBasePremium = (items: Item[]): number =>
66	  items.reduce((total, item) => total + itemBasePremium(item), 0);
67	
68	const quote = (step: QuoteStep): StepResult => {
69	  const basePremium = policyBasePremium(step.items);
70	  const modifiedPremium = addPercent(
71	    basePremium,
72	    FIRST_INSURANCE_SURCHARGE_PERCENT,
73	  );
74	  // The processing fee is added last, after all percentage modifiers.
75	  const premium = modifiedPremium + PROCESSING_FEE;
76	  return { premium: roundPremium(premium) };
77	};
78	
79	export const runScenario = (scenario: Scenario): ScenarioResult => {
80	  const results = scenario.steps.map((step) => quote(step as QuoteStep));
81	  return { results };
82	};
