const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return quote(step.items);
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results = scenario.steps.map(runStep);
  return { results };
};
